import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";

type InventoryItem = {
  id: string;
  name: string;
  rarity: string;
  price: string | number;
  location: string;
};

type InventoryRowProps = {
  item: InventoryItem;
  selected: boolean;
  onToggle: (id: string) => void;
};

function getRarityClass(rarity: string) {
  if (rarity === "Covert") {
    return "text-[var(--danger)]";
  }

  if (rarity === "Classified") {
    return "text-[var(--accent)]";
  }

  return "text-[var(--text-muted)]";
}

const cellBase = "border-y border-[var(--border)] py-4";

export default function InventoryRow({
  item,
  selected,
  onToggle
}: InventoryRowProps) {
  return (
    <TableRow className="border-0 bg-[var(--panel)] text-sm text-[var(--text)] transition-colors hover:bg-[var(--panel-soft)]">
      <TableCell
        className={`${cellBase} w-[32px] rounded-l-xl border-l pl-4`}
      >
        <Checkbox
          checked={selected}
          className="border-[var(--border)] data-[state=checked]:bg-[var(--accent)] data-[state=checked]:text-black"
          onCheckedChange={() => onToggle(item.id)}
        />
      </TableCell>
      <TableCell className={`${cellBase} w-[40px] px-2`}>
        <div className="h-9 w-9 rounded-md border border-[var(--border)] bg-[var(--panel-soft)]" />
      </TableCell>
      <TableCell className={`${cellBase} px-3 truncate`}>
        {item.name}
      </TableCell>
      <TableCell className={`${cellBase} px-3 ${getRarityClass(item.rarity)}`}>
        {item.rarity}
      </TableCell>
      <TableCell className={`${cellBase} px-3`}>{item.price}</TableCell>
      <TableCell
        className={`${cellBase} rounded-r-xl border-r px-4 text-[var(--text-muted)]`}
      >
        {item.location}
      </TableCell>
    </TableRow>
  );
}
